// Every setting can be overridden by query string:
//   /webhook/dev-briefing?city=Bangalore&lat=12.97&lon=77.59&topics=ai,rust&base=EUR
const q = $input.first().json.query || {};

const city = {
  name: q.city || 'Chennai',
  lat: Number(q.lat) || 13.0827,
  lon: Number(q.lon) || 80.2707,
};
const keywords = String(q.topics || 'ai,llm,python,java,security,startup,open source,database,linux')
  .split(',').map((s) => s.trim().toLowerCase()).filter(Boolean);
const base = String(q.base || 'USD').toUpperCase().replace(/[^A-Z]/g, '').slice(0, 3) || 'USD';
const hnLimit = Math.min(Math.max(Number(q.hn) || 30, 5), 60);
const since = new Date(Date.now() - 7 * 864e5).toISOString().slice(0, 10);

return [{
  json: {
    city, keywords, base, hnLimit, since,
    weatherUrl:
      'https://api.open-meteo.com/v1/forecast?latitude=' + city.lat + '&longitude=' + city.lon +
      '&current=temperature_2m,apparent_temperature,relative_humidity_2m,weather_code,wind_speed_10m' +
      '&daily=temperature_2m_max,temperature_2m_min,precipitation_probability_max,weather_code' +
      '&timezone=auto&forecast_days=3',
    githubUrl:
      'https://api.github.com/search/repositories?q=created:%3E' + since +
      '&sort=stars&order=desc&per_page=10',
    fxUrl: 'https://open.er-api.com/v6/latest/' + base,
  },
}];

// HN returns a bare array of ids. Parsed here rather than in the HTTP node,
// because n8n splits JSON arrays inconsistently depending on element type.
const cfg = $('Config').first().json;
const body = $input.first().json;

let ids = [];
try {
  ids = JSON.parse(body.raw || '[]');
} catch (e) {
  ids = [];
}

// Always emit at least one item so this branch still reaches the Merge node.
if (!Array.isArray(ids) || ids.length === 0) {
  return [{ json: { id: null } }];
}
return ids.slice(0, cfg.hnLimit).map((id) => ({ json: { id } }));

// Score = HN points, boosted for every one of your topics the title mentions.
const cfg = $('Config').first().json;

const stories = $input.all()
  .map((i) => i.json)
  .filter((s) => s && s.type === 'story' && s.title && !s.dead && !s.deleted)
  .map((s) => {
    const words = ' ' + s.title.toLowerCase().replace(/[^a-z0-9+#. ]/g, ' ') + ' ';
    const matched = cfg.keywords.filter((k) => words.includes(' ' + k + ' '));
    const points = s.score || 0;
    return {
      title: s.title,
      url: s.url || 'https://news.ycombinator.com/item?id=' + s.id,
      discuss: 'https://news.ycombinator.com/item?id=' + s.id,
      points,
      comments: s.descendants || 0,
      matched,
      rank: points * (1 + 0.75 * matched.length),
    };
  })
  .sort((a, b) => b.rank - a.rank);

return [{
  json: {
    section: 'hn',
    ok: stories.length > 0,
    reason: stories.length ? '' : 'no stories returned',
    forYou: stories.filter((s) => s.matched.length > 0).slice(0, 8),
    top: stories.filter((s) => s.matched.length === 0).slice(0, 5),
    scanned: stories.length,
  },
}];

const r = $input.first().json;

if (r.error || !Array.isArray(r.items)) {
  return [{ json: { section: 'github', ok: false, reason: (r.error && r.error.message) || r.message || 'no data', repos: [] } }];
}

return [{
  json: {
    section: 'github',
    ok: true,
    since: $('Config').first().json.since,
    repos: r.items.slice(0, 8).map((x) => ({
      name: x.full_name,
      url: x.html_url,
      description: (x.description || '').slice(0, 140),
      stars: x.stargazers_count,
      language: x.language || 'n/a',
    })),
  },
}];

const w = $input.first().json;
const cfg = $('Config').first().json;

const WMO = {
  0: 'Clear', 1: 'Mainly clear', 2: 'Partly cloudy', 3: 'Overcast',
  45: 'Fog', 48: 'Fog', 51: 'Light drizzle', 53: 'Drizzle', 55: 'Heavy drizzle',
  61: 'Light rain', 63: 'Rain', 65: 'Heavy rain', 66: 'Freezing rain', 67: 'Freezing rain',
  71: 'Light snow', 73: 'Snow', 75: 'Heavy snow', 80: 'Showers', 81: 'Showers', 82: 'Violent showers',
  95: 'Thunderstorm', 96: 'Thunderstorm, hail', 99: 'Thunderstorm, hail',
};
const label = (c) => WMO[c] || 'Unknown';

if (w.error || !w.current || !w.daily) {
  return [{ json: { section: 'weather', ok: false, city: cfg.city.name, reason: (w.error && w.error.message) || 'no data' } }];
}

const days = w.daily.time.map((d, i) => ({
  date: d,
  max: w.daily.temperature_2m_max[i],
  min: w.daily.temperature_2m_min[i],
  rain: w.daily.precipitation_probability_max[i],
  sky: label(w.daily.weather_code[i]),
}));

const alerts = [];
if (days.some((d) => d.rain >= 70)) alerts.push('High chance of rain in the next 3 days - carry an umbrella.');
if (w.current.apparent_temperature >= 38) alerts.push('Feels like ' + w.current.apparent_temperature + ' C right now - stay hydrated.');

return [{
  json: {
    section: 'weather',
    ok: true,
    city: cfg.city.name,
    now: {
      temp: w.current.temperature_2m,
      feels: w.current.apparent_temperature,
      humidity: w.current.relative_humidity_2m,
      wind: w.current.wind_speed_10m,
      sky: label(w.current.weather_code),
    },
    days,
    alerts,
  },
}];

const r = $input.first().json;
const base = $('Config').first().json.base;
const WANT = ['INR', 'USD', 'EUR', 'GBP', 'JPY', 'AED', 'SGD'].filter((c) => c !== base);

if (r.error || r.result !== 'success' || !r.rates) {
  return [{ json: { section: 'fx', ok: false, base, reason: (r.error && r.error.message) || r['error-type'] || 'no data' } }];
}

return [{
  json: {
    section: 'fx',
    ok: true,
    base,
    updated: r.time_last_update_utc,
    rates: WANT.filter((c) => r.rates[c] != null).map((c) => ({ code: c, rate: r.rates[c] })),
  },
}];

// Merge appends all four branches; pick each one out by its section tag.
const parts = {};
for (const item of $input.all()) parts[item.json.section] = item.json;
const hn = parts.hn || {};
const github = parts.github || {};
const weather = parts.weather || {};
const fx = parts.fx || {};
const cfg = $('Config').first().json;

const esc = (v) => String(v == null ? '' : v)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const down = (name, why) => '<p class="muted">' + esc(name) + ' unavailable right now (' + esc(why || 'no data') + ').</p>';

const story = (s) =>
  '<li><a href="' + esc(s.url) + '">' + esc(s.title) + '</a>' +
  '<div class="meta">' + s.points + ' pts &middot; <a href="' + esc(s.discuss) + '">' + s.comments + ' comments</a>' +
  (s.matched.length ? ' &middot; ' + s.matched.map((m) => '<span class="tag">' + esc(m) + '</span>').join(' ') : '') +
  '</div></li>';

const hnHtml = hn.ok
  ? '<h3>Matching your topics</h3>' +
    (hn.forYou.length ? '<ol>' + hn.forYou.map(story).join('') + '</ol>' : '<p class="muted">Nothing on the front page matches your topics right now.</p>') +
    '<h3>Also trending</h3><ol>' + hn.top.map(story).join('') + '</ol>' +
    '<p class="muted">Ranked ' + hn.scanned + ' front-page stories.</p>'
  : down('Hacker News', hn.reason);

const ghHtml = github.ok
  ? '<ol>' + github.repos.map((r) =>
      '<li><a href="' + esc(r.url) + '">' + esc(r.name) + '</a> <span class="tag">' + esc(r.language) + '</span>' +
      '<div class="meta">&#9733; ' + r.stars.toLocaleString('en-IN') + ' &middot; ' + esc(r.description) + '</div></li>'
    ).join('') + '</ol><p class="muted">Repos created since ' + esc(github.since) + ', ranked by stars.</p>'
  : down('GitHub', github.reason);

const wxHtml = weather.ok
  ? '<div class="big">' + Math.round(weather.now.temp) + '&deg;C <small>' + esc(weather.now.sky) + '</small></div>' +
    '<div class="meta">Feels ' + Math.round(weather.now.feels) + '&deg;C &middot; humidity ' + weather.now.humidity + '% &middot; wind ' + weather.now.wind + ' km/h</div>' +
    '<table>' + weather.days.map((d) =>
      '<tr><td>' + esc(new Date(d.date).toLocaleDateString('en-IN', { weekday: 'short', day: 'numeric', month: 'short' })) + '</td>' +
      '<td>' + esc(d.sky) + '</td><td>' + Math.round(d.min) + '&ndash;' + Math.round(d.max) + '&deg;</td><td>' + d.rain + '% rain</td></tr>'
    ).join('') + '</table>' +
    weather.alerts.map((a) => '<div class="alert">' + esc(a) + '</div>').join('')
  : down('Weather', weather.reason);

const fxHtml = fx.ok
  ? '<table>' + fx.rates.map((r) =>
      '<tr><td>1 ' + esc(fx.base) + '</td><td>=</td><td><b>' + r.rate.toLocaleString('en-IN', { maximumFractionDigits: 4 }) + '</b> ' + esc(r.code) + '</td></tr>'
    ).join('') + '</table><p class="muted">Updated ' + esc(fx.updated) + '</p>'
  : down('Exchange rates', fx.reason);

const now = new Date().toLocaleString('en-IN', { dateStyle: 'full', timeStyle: 'short' });
const healthy = [hn.ok, github.ok, weather.ok, fx.ok].filter(Boolean).length;

const html = '<!doctype html><html lang="en"><head><meta charset="utf-8">' +
'<meta name="viewport" content="width=device-width,initial-scale=1"><title>Dev Daily Briefing</title><style>' +
':root{--bg:#f6f7f9;--card:#fff;--ink:#1f2328;--muted:#656d76;--line:#e4e7eb;--accent:#0969da;--tag:#ddf4ff;--warn:#fff8c5}' +
'@media (prefers-color-scheme:dark){:root{--bg:#0d1117;--card:#161b22;--ink:#e6edf3;--muted:#8d96a0;--line:#30363d;--accent:#4493f8;--tag:#0c2d6b;--warn:#3d2e00}}' +
'*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:15px/1.5 -apple-system,Segoe UI,Roboto,sans-serif}' +
'header{max-width:1100px;margin:0 auto;padding:28px 16px 8px}h1{margin:0;font-size:24px}' +
'.grid{max-width:1100px;margin:0 auto;padding:16px;display:grid;gap:16px;grid-template-columns:repeat(auto-fit,minmax(300px,1fr))}' +
'section{background:var(--card);border:1px solid var(--line);border-radius:10px;padding:18px;min-width:0}.wide{grid-column:1/-1}' +
'h2{margin:0 0 10px;font-size:16px}h3{margin:14px 0 6px;font-size:13px;text-transform:uppercase;letter-spacing:.04em;color:var(--muted)}' +
'ol{margin:0;padding-left:20px}li{margin:0 0 9px;overflow-wrap:anywhere}a{color:var(--accent);text-decoration:none}a:hover{text-decoration:underline}' +
'.meta,.muted{color:var(--muted);font-size:13px}.tag{background:var(--tag);border-radius:10px;padding:1px 7px;font-size:11px}' +
'.big{font-size:34px;font-weight:700}.big small{font-size:15px;font-weight:400;color:var(--muted)}' +
'table{width:100%;border-collapse:collapse;margin-top:10px}td{padding:6px 4px;border-top:1px solid var(--line);font-size:14px}' +
'.alert{background:var(--warn);border-radius:6px;padding:8px 10px;margin-top:10px;font-size:13px}' +
'</style></head><body><header><h1>Dev Daily Briefing</h1>' +
'<div class="muted">' + esc(now) + ' &middot; ' + esc(cfg.city.name) + ' &middot; ' + healthy + '/4 sources live &middot; topics: ' + esc(cfg.keywords.join(', ')) + '</div></header>' +
'<div class="grid"><section class="wide"><h2>Hacker News</h2>' + hnHtml + '</section>' +
'<section><h2>Rising on GitHub this week</h2>' + ghHtml + '</section>' +
'<section><h2>Weather &middot; ' + esc(weather.city || cfg.city.name) + '</h2>' + wxHtml + '</section>' +
'<section><h2>Exchange rates</h2>' + fxHtml + '</section></div></body></html>';

return [{ json: { html, healthy } }];
